questionvariables.text:
/* 1. Define segments along the baseline AD */
d1: 4 + rand(4);
d2: 5 + rand(5);
d3: 4 + rand(4);

/* 2. Define perpendicular offsets (heights) */
/* Force h1 and h2 into distinct ranges to guarantee a jagged, irregular shape */
h_short: 3 + rand(3); /* 3 to 5 */
h_tall: 8 + rand(5);  /* 8 to 12 */

/* Randomly swap them so the field can slope up or slope down */
swap: rand(2);
h1: if swap = 1 then h_short else h_tall;
h2: if swap = 1 then h_tall else h_short;

/* 3. Calculate areas of individual shapes */
area1: float((1/2) * d1 * h1);
area2: float((1/2) * (h1 + h2) * d2);
area3: float((1/2) * d3 * h2);

/* 4. Total Area */
ta: float(area1 + area2 + area3);

/* Common Mistakes for PRT */
m1: float((d1 * h1) + ((h1 + h2) * d2) + (d3 * h2));      /* Forgot the 1/2 factor entirely */
m2: float((1/2) * (h1 + h2) * (d1 + d2 + d3));            /* Treated the whole shape as one giant trapezium */
